<script lang="ts">
 import {onMount} from 'svelte';
 import {sessionRequest} from '$lib/admin';
 let runtime:any=$state(null),training:any=$state(null),error=$state(''),notice=$state(''),busy=$state(false),bee=$state('drift'),rights=$state(false),bars:{time:number;close:number}[]=$state([]),filename=$state('');
 async function refresh(){busy=true;error='';try{const [status,report]=await Promise.all([sessionRequest('/api/runtime/admin/status'),sessionRequest('/api/runtime/admin/training')]);runtime=status;training=report;}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function configure(data:Record<string,unknown>){busy=true;error='';try{await sessionRequest('/api/runtime/admin/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});notice='Runtime configuration saved by server.';await refresh();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function cycle(){busy=true;error='';try{const result=await sessionRequest('/api/runtime/admin/cycle',{method:'POST'});notice=JSON.stringify(result);await refresh();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function mode(value:string){busy=true;error='';try{await sessionRequest('/api/runtime/mode',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:value})});await refresh();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function parse(e:Event){bars=[];error='';filename='';const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;try{if(file.size>500000)throw new Error('CSV must be smaller than 500 KB.');const lines=(await file.text()).trim().split(/\r?\n/);const header=lines.shift()?.split(',').map(s=>s.trim().toLowerCase())??[];const timeIndex=header.findIndex(s=>['timestamp','time'].includes(s)),closeIndex=header.indexOf('close');if(timeIndex<0||closeIndex<0)throw new Error('CSV header must contain timestamp (or time) and close.');if(lines.length>5000)throw new Error('Maximum 5,000 bars per import.');const parsed=lines.filter(s=>s.trim()).map((line,i)=>{const row=line.split(',');let time=Number(row[timeIndex]);if(!Number.isFinite(time))time=Date.parse(row[timeIndex]);else if(time<100000000000)time*=1000;const close=Number(row[closeIndex]);if(!Number.isFinite(time)||time<=0||time>Date.now()-300000||!Number.isFinite(close)||close<=0)throw new Error(`Invalid or unclosed bar on CSV row ${i+2}.`);return {time,close};}).sort((a,b)=>a.time-b.time);if(!parsed.length)throw new Error('CSV contains no observations.');if(parsed.some((b,i)=>i>0&&b.time===parsed[i-1].time))throw new Error('Duplicate timestamps are not allowed.');bars=parsed;filename=file.name;}catch(e){error=e instanceof Error?e.message:String(e);}}
 async function upload(){busy=true;error='';try{if(!rights||!bars.length)throw new Error('Confirm retention rights and select valid bars.');const result=await sessionRequest('/api/runtime/admin/datasets',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({bee,bars,retentionRightsConfirmed:rights})});notice=`${result.samples} bars retained for ${result.bee}: ${result.status}.`;bars=[];filename='';rights=false;await refresh();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 function count(provider:string,period:string){return runtime?.usage?.[provider]?.[period]?.count??0;}
 function window(provider:string,period:string){return runtime?.usage?.[provider]?.[period]?.window??'No reservations recorded';}
 function cap(p:any,period:string){return p.limits?.[period]===undefined?'No configured cap':p.limits[period]===0?'Blocked':`${Math.max(1,Math.floor(p.limits[period]*.9))} / ${p.limits[period]} cap`;}
 function bytes(provider:string){return (runtime?.usage?.[provider]?.bytes??[]).filter((b:any)=>b.at>Date.now()-30*86400000).reduce((s:number,b:any)=>s+b.bytes,0);}
 onMount(()=>{void refresh();});
</script>
<section class="runtime"><div class="title"><div><span class="eyebrow">AUTONOMOUS RUNTIME</span><h2>Hive operations</h2></div><button disabled={busy} onclick={refresh}>Refresh evidence ↻</button></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}{#if runtime}<div class="summary"><article><span>Execution mode</span><strong>{runtime.config?.mode??'unverified'}</strong><small>{runtime.liveReady?'Venue verified':'Live locked · venue authorization required'}</small></article><article><span>Autonomous decisions</span><strong>{runtime.config?.paused?'Paused':'Enabled'}</strong><small>{runtime.config?.feeds?.length??0} configured feeds</small></article><article><span>Training schedule</span><strong>{runtime.training?.localTime??'Not verified'}</strong><small>Cron {training?.cron??runtime.training?.schedule??'unverified'} UTC</small></article></div><div class="controls"><button disabled={busy} onclick={()=>configure({paused:!runtime.config.paused})}>{runtime.config.paused?'Resume configured paper hive':'Pause autonomous hive'}</button><button disabled={busy||runtime.config?.mode==='paper'} onclick={()=>mode('paper')}>Paper mode</button><button disabled={busy||!runtime.liveReady} onclick={()=>mode('live')}>Live mode {runtime.liveReady?'':'· locked'}</button></div><button disabled={busy||runtime.config?.paused} onclick={cycle}>Evaluate paper cycle now</button>{#if runtime.lastCycle}<p class="muted">Last cycle: {runtime.lastCycle.at} � {runtime.lastCycle.outcomes?.map((o:any)=>`${o.symbol}: ${o.status} ${o.error??o.reason??'closed-bar decision'}`).join('; ')}</p>{/if}<p class="muted">Pausing prevents new automated decisions. It does not close existing positions. Learned candidates stay in shadow mode until forward validation; no return is guaranteed.</p><div class="table-scroll"><table><thead><tr><th>Bee / model</th><th>State</th><th>Autonomy</th></tr></thead><tbody>{#each runtime.config?.bees??[] as bot}<tr><td><strong>{bot.name}</strong><small>{bot.model}</small></td><td>{bot.executable?(bot.enabled?'Enabled':'Paused'):'Research · untrained'}</td><td><button disabled={busy||!bot.executable} onclick={()=>configure({bees:[{id:bot.id,enabled:!bot.enabled}]})}>{bot.executable?(bot.enabled?'Pause Bee':'Enable paper Bee'):'Training evidence required'}</button></td></tr>{/each}</tbody></table></div><h3>Provider budgets & endpoint counters</h3><p class="muted">Counters record runtime reservations, including failed upstream requests. Provider-dashboard consumption outside this application is not visible here. Budgets reserve 10% headroom. Unknown entitlements remain blocked.</p><div class="providers">{#each runtime.providers??[] as provider}<article class="provider"><div class="provider-title"><h4>{provider.id}</h4><span class:enabled={provider.enabled&&provider.configured}>{!provider.configured?'Key not configured':provider.enabled?'Enabled':'Disabled · confirm entitlement'}</span></div><div class="budget">{#each ['minute','day','month'] as period}<div><span>{period}</span><strong>{count(provider.id,period)} <small>used · {cap(provider,period)}</small></strong><small>{window(provider.id,period)} UTC</small>{#if provider.limits?.[period]>0}<progress max={Math.max(1,Math.floor(provider.limits[period]*.9))} value={count(provider.id,period)} aria-label={`${provider.id} ${period} request budget`}></progress>{/if}</div>{/each}</div>{#if provider.limits?.bytes30d}<p class="muted">Rolling 30-day reserved bytes: {bytes(provider.id).toLocaleString()} / {Math.floor(provider.limits.bytes30d*.9).toLocaleString()} budget ({provider.limits.bytes30d.toLocaleString()} hard cap). Each request reserves 1 MB conservatively.</p>{/if}<details><summary>Endpoint usage</summary>{#each provider.endpoints??[] as endpoint}<div class="endpoint"><code>{endpoint}</code><span>{#each ['minute','day','month'] as period}{runtime.usage?.[provider.id]?.endpoints?.[endpoint]?.[period]?.count??0} / {period} {period!=='month'?'· ':''}{/each}</span></div>{:else}<p class="muted">No verified endpoints enabled.</p>{/each}</details><p class="muted">Retention: {runtime.config.providers?.[provider.id]?.retentionAllowed?'permitted by configuration':'disabled'} · Redistribution: {runtime.config.providers?.[provider.id]?.redistributionAllowed?'permitted by configuration':'disabled'}</p></article>{/each}</div><h3>Retained-data training</h3><p class="muted">Import licensed, closed bars from existing exports. This action writes to R2, outside Convex. It does not fetch provider data or start paid training. Minimum 1,200 bars for chronological evaluation; maximum 5,000 bars. Import replaces the selected Bee dataset. Keep one instrument and consistent intervals per dataset.</p><form class="dataset" onsubmit={(e)=>{e.preventDefault();void upload();}}><label>Target Bee<select bind:value={bee}>{#each (runtime.config?.bees??[]).filter((b:any)=>b.executable) as bot}<option value={bot.id}>{bot.name}</option>{/each}</select></label><label>Historical CSV<input type="file" accept=".csv,text/csv" onchange={parse}/><small>Header: timestamp,close · ISO date, Unix seconds or milliseconds</small></label>{#if bars.length}<p>{filename} · {bars.length.toLocaleString()} chronological bars · {new Date(bars[0].time).toLocaleDateString()} – {new Date(bars.at(-1)!.time).toLocaleDateString()}</p>{/if}<label class="check"><input type="checkbox" bind:checked={rights}/>I confirm retention rights and that all imported bars belong to the selected Bee’s instrument.</label><button disabled={busy||!rights||!bars.length}>Import retained dataset</button></form><div class="training">{#each training?.results??[] as report}<article><div class="provider-title"><strong>{report.bee}</strong><span>{report.result?.status??'No report'}</span></div><p>{report.result?.at?new Date(report.result.at).toLocaleString('en-GB',{timeZone:'Africa/Lagos'})+' Nigeria time':'No completed training run recorded'}</p>{#if report.result?.reason}<p>{report.result.reason}</p>{/if}{#if report.result?.metrics}<dl>{#each Object.entries(report.result.metrics) as [name,value]}<div><dt>{name}</dt><dd>{typeof value==='number'?value.toLocaleString('en-US',{maximumFractionDigits:6}):String(value)}</dd></div>{/each}</dl>{/if}</article>{/each}</div><h3>Paper accounts</h3><div class="table-scroll"><table><thead><tr><th>Bee / instrument</th><th>Simulated cash</th><th>Simulated equity</th><th>Simulated P&amp;L</th><th>Trades</th><th>Last decision</th></tr></thead><tbody>{#each Object.entries(runtime.paper??{}) as [id,account]}{@const p=account as any}<tr><td>{id}</td><td>{p.cash?.toFixed(2)??'—'}</td><td>{p.equity?.toFixed(2)??'—'}</td><td>{p.pnl?.toFixed(2)??'—'}</td><td>{p.trades??0}</td><td>{p.lastDecision?.action??'—'}<small>{p.lastDecision?.reason??'No decision recorded'}</small></td></tr>{:else}<tr><td colspan="6">No runtime paper accounts yet. An enabled Bee requires an eligible configured feed and enough closed bars.</td></tr>{/each}</tbody></table></div>{:else}<p class="muted">{busy?'Loading verified runtime evidence…':'Runtime is not connected. No background activity is claimed.'}</p>{/if}</section>
<style>.runtime{background:#12161e;border:1px solid #2a303b;border-radius:12px;padding:22px;margin-bottom:22px}.title,.provider-title{display:flex;justify-content:space-between;align-items:center;gap:14px}h2{font-size:20px;margin:8px 0}h3{font-size:16px;margin:32px 0 12px}h4{margin:0;font-size:15px;text-transform:capitalize}.eyebrow{font-size:9px;letter-spacing:2px;color:#b79e67}button{border:1px solid #41413b;border-radius:6px;padding:9px 12px;color:#e6bf73;background:#e6b85c09;font-size:11px}button:disabled{opacity:.45}.summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:20px 0}.summary article{display:grid;gap:10px;border:1px solid #2b3442;border-radius:8px;padding:17px}.summary span,.budget>div>span{font-size:10px;text-transform:uppercase;color:#8995a8;letter-spacing:1px}.summary strong{font-size:20px;font-weight:550}.summary small,.muted,small{font-size:11px;color:#8a97aa;line-height:1.7}.controls{display:flex;gap:10px;flex-wrap:wrap}.muted{line-height:1.8}.table-scroll{overflow:auto}table{width:100%;font-size:12px;border-collapse:collapse;text-align:left;margin:15px 0}td,th{border-bottom:1px solid #2a303c;padding:13px 10px;min-width:100px}th{color:#8390a3;font-size:10px;font-weight:500}td small{display:block;font-size:10px}.providers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.provider{padding:18px;border:1px solid #2a3340;border-radius:9px;min-width:0}.provider-title>span{color:#d5a875;font-size:9px}.provider-title>.enabled{color:#70c7aa}.budget{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:18px 0}.budget>div{display:grid;gap:6px}.budget strong{font-size:17px;font-weight:500}.budget strong small{display:block;font-size:9px}.budget>div>small{font-size:8px;overflow-wrap:anywhere}progress{width:100%;height:5px;accent-color:#e6b85c}.endpoint{display:flex;justify-content:space-between;gap:14px;border-bottom:1px solid #252d39;padding:10px 0;font-size:10px;overflow-wrap:anywhere}.endpoint span{color:#8c9aaf;font-size:9px}.endpoint code{font-size:10px}summary{font-size:11px;color:#e1bd74;cursor:pointer}.dataset{border:1px solid #2a3340;border-radius:9px;padding:20px;display:grid;gap:17px}.dataset label{display:grid;gap:7px;font-size:12px;color:#b4bfce}.dataset input:not([type=checkbox]),select{padding:11px;background:#0d121a;border:1px solid #364153;border-radius:6px;max-width:100%;color:#dce4f1}.dataset .check{display:flex;align-items:flex-start;gap:10px;line-height:1.7}.dataset .check input{margin-top:4px}.dataset button{justify-self:start}.training{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:18px 0}.training article{border:1px solid #293440;border-radius:8px;padding:16px}.training p{font-size:10px;line-height:1.8;color:#8e9bb0}.training dl{font-size:11px;margin:0}.training dl div{display:flex;justify-content:space-between;padding:7px 0;border-top:1px solid #28323f}.training dt{color:#929eb0}.training dd{margin:0}.error,.notice{padding:14px;border-radius:7px;font-size:12px;line-height:1.6}.error{color:#f5a2ab;background:#e76d7b12}.notice{color:#8dd9c1;background:#67c4a612}@media(max-width:1000px){.providers{grid-template-columns:1fr}.training{grid-template-columns:1fr}}@media(max-width:640px){.runtime{padding:16px}.title{align-items:flex-start}.title button{font-size:9px;padding:8px}.summary{grid-template-columns:1fr;gap:9px}.summary article{padding:13px}.summary strong{font-size:18px}.budget{gap:7px}.budget strong{font-size:14px}.provider{padding:14px}.provider-title{align-items:flex-start}.provider-title>span{text-align:right;max-width:55%}.dataset{padding:14px}.endpoint{flex-direction:column;gap:4px}}
</style>
